 void ShowControls(){if(testing||controllerControls)return;bar=new RecorderBar(()=>Pause(),()=>OnUi(async()=>await Finish()));var screen=Screen.PrimaryScreen;bar.Location=new Point(screen.WorkingArea.Right-bar.Width-16,screen.WorkingArea.Top+16);bar.Show();tray=new NotifyIcon{Icon=owner.Icon,Text="Xiaoma Player + Recorder · Recording in progress",Visible=true};var menu=new ContextMenuStrip();menu.Items.Add("Pause / Resume",null,(s,e)=>Pause());menu.Items.Add("End and review",null,(s,e)=>OnUi(async()=>await Finish()));tray.ContextMenuStrip=menu;}
 void OnUi(Func<Task> action){try{owner.BeginInvoke(new Action(async()=>{try{await action();}catch(Exception e){captureError=e.Message;}}));}catch{}}
 void Release(bool removeTemporary=false){var oldCaptures=captures.ToArray();captures.Clear();_ = Task.Run(()=>{foreach(var capture in oldCaptures)try{capture.Dispose();}catch{}});audioBuffers.Clear();mixer=null;lock(frameGate){queuedFrames.Clear();freeFrames.Clear();}try{if(child!=null&&!child.HasExited)child.Kill();child?.Dispose();}catch{}child=null;if(bar!=null){bar.Dispose();bar=null;}if(tray!=null){tray.Dispose();tray=null;}try{if(audioEncoder!=null&&!audioEncoder.HasExited)audioEncoder.Kill();audioEncoder?.Dispose();}catch{}audioEncoder=null;if(removeTemporary)try{foreach(var temp in new[]{videoFile,audioFile,sessionDirectory==null?null:Path.Combine(sessionDirectory,"recovery.json")})if(temp!=null&&File.Exists(temp))File.Delete(temp);if(sessionDirectory!=null&&Directory.Exists(sessionDirectory))Directory.Delete(sessionDirectory);}catch{}}
 public void Dispose(){disposed=true;clock.Stop();stopRequested=true;Wake();timer.Stop();timer.Dispose();try{if(child!=null&&!child.HasExited)child.Kill();}catch{}try{if(audioEncoder!=null&&!audioEncoder.HasExited)audioEncoder.Kill();}catch{}try{Task.WhenAll(captureTask??Task.CompletedTask,videoTask??Task.CompletedTask,audioTask??Task.CompletedTask).Wait(2000);}catch{}Release();captureWake.Dispose();encodeWake.Dispose();audioWake.Dispose();frameReady.Dispose();bufferReleased.Dispose();}
}
